
-- Supabase schema for DN Classic Monster Cards
-- Run this in Supabase SQL Editor

create table if not exists nests (
  id serial primary key,
  name text unique not null,
  created_at timestamp default now()
);

create table if not exists monster_cards (
  card_no int primary key,
  name text not null,
  nest_id int references nests(id),
  created_at timestamp default now()
);

create table if not exists card_stats (
  id serial primary key,
  card_no int references monster_cards(card_no) on delete cascade,
  stat_name text not null,
  rarity int not null check (rarity between 1 and 5),
  value int not null,
  unique(card_no, stat_name, rarity)
);

create table if not exists stat_types (
  name text primary key
);

alter table nests enable row level security;
alter table monster_cards enable row level security;
alter table card_stats enable row level security;
alter table stat_types enable row level security;

drop policy if exists "Allow read all" on nests;
create policy "Allow read all" on nests for select using (true);
drop policy if exists "Allow read all" on monster_cards;
create policy "Allow read all" on monster_cards for select using (true);
drop policy if exists "Allow read all" on card_stats;
create policy "Allow read all" on card_stats for select using (true);
drop policy if exists "Allow read all" on stat_types;
create policy "Allow read all" on stat_types for select using (true);

drop policy if exists "Allow insert" on nests;
create policy "Allow insert" on nests for insert with check (true);
drop policy if exists "Allow insert" on monster_cards;
create policy "Allow insert" on monster_cards for insert with check (true);
drop policy if exists "Allow insert" on card_stats;
create policy "Allow insert" on card_stats for insert with check (true);
drop policy if exists "Allow insert" on stat_types;
create policy "Allow insert" on stat_types for insert with check (true);
drop policy if exists "Allow delete" on nests;
create policy "Allow delete" on nests for delete using (true);
drop policy if exists "Allow delete" on monster_cards;
create policy "Allow delete" on monster_cards for delete using (true);
drop policy if exists "Allow delete" on card_stats;
create policy "Allow delete" on card_stats for delete using (true);




-- stat_types
